const hasCronFields = raw.linkedin_query || raw.leads_per_run;
const merged = hasCronFields ? raw : ((raw && raw.body && typeof raw.body === 'object') ? { ...raw.body, ...raw } : raw);
const env = $env || {};
const runConfig = {
  run_id: `prospect-run-${Date.now()}`,
  started_at: new Date().toISOString(),
  linkedin_query: merged.linkedin_query || env.LINKEDIN_SEARCH_QUERY || 'operations manager ai automation latam',
  leads_per_run: Number(merged.leads_per_run || env.LEADS_PER_RUN || 25),
  fit_threshold: Number(merged.fit_threshold || env.LEAD_FIT_THRESHOLD || 70),
  dry_run: Boolean(merged.dry_run),
  test_leads: Array.isArray(merged.test_leads) ? merged.test_leads : null,
  tenant: 'levinnovation',
};
return [{ json: runConfig }];

